use std::{fs,path::Path,process::{Command,Stdio}};
fn main(){let args:Vec<_>=std::env::args().collect();let src=Path::new(&args[1]);let root=Path::new(&args[2]);assert!(!root.exists());fs::create_dir(root).unwrap();let mut files:Vec<_>=fs::read_dir(src).unwrap().map(|p|p.unwrap().path()).filter(|p|p.file_name().unwrap().to_string_lossy().ends_with("-PUBLIC.txt")).collect();files.sort();assert_eq!(files.len(),5,"all_admitted_cases_required");let bin=std::env::current_exe().unwrap().with_file_name("source-lift13");for f in files{let stem=f.file_name().unwrap().to_str().unwrap().trim_end_matches("-PUBLIC.txt");let cert=src.join(format!("{stem}-CERT.txt"));let s=Command::new(&bin).arg(&f).arg(cert).stdout(Stdio::from(fs::File::create(root.join(format!("{stem}.stdout"))).unwrap())).stderr(Stdio::from(fs::File::create(root.join(format!("{stem}.stderr"))).unwrap())).status().unwrap();fs::write(root.join(format!("{stem}.status")),format!("exit={:?}\n",s.code())).unwrap();assert!(s.success(),"admitted_weil_failure {stem}");println!("CASE_PASS {stem}");}println!("PASS all_five_admitted_weil_cases=true extension_counts_used=false");}
